import json,hashlib,pathlib,datetime,fitz
p=pathlib.Path('experiments/2026-10-24-harappa-context-extension'); raw=pathlib.Path(r'D:/projects/indus_valley_script/data/raw/2026-10-24-harappa-context-extension')
if (p/'summary-v1.json').exists() or (raw/'context-records-v1.json').exists():
 raise SystemExit('Frozen v1 output exists; copy code to a new dated/versioned run before replay.')
source=pathlib.Path('research/corpus/primary/kenoyer_meadow2010_inscribed_objects.pdf')
d=fitz.open(source); pages=list(range(1,7))+list(range(9,16))
(raw/'2010-selected-text.txt').write_text('\n'.join(f'PDF PAGE {i}\n'+d[i-1].get_text() for i in pages),encoding='utf8')
def rec(cisi,pages,registration=None,lot=None,item=None,mound=None,deposit=None,period=None,basis=None,eligibility=None,conflict=None):
 return dict(cisi=cisi,source_id='KM2010',pdf_pages=pages,registration=registration,excavation_unit=lot,item=item,mound=mound,deposit=deposit,period=period,dating_basis=basis,manufacture_date=None,radiocarbon_sample=None,later_cohort_disposition=eligibility,conflict=conflict)
rows=[
rec('H-1657',[3],'H99-4064','8796','1',basis='Footnote demonstrates complete registration syntax; no individual context or date.',eligibility='unresolved context; no period from inspected primary source'),
rec('H-2587',[9,10],lot=None,item='1',period='2',basis='Button-seal discussion; no individual stratigraphic attribution in inspected passage.',eligibility='outside mature-period text comparison; lot must be resolved',conflict='Page 9 prose H96/7158-01; page 10 caption H96/7458-0001. Neither is silently preferred.'),
rec('H-2588',[10,12],'H98-3493','8314','1',deposit='mixed context',period='3C',basis='Reassigned from Period 2 by carving technique and glazed surface.',eligibility='exclude from independent stratigraphic clock; geometric button seal'),
rec('H-1688',[10],mound='E',deposit='street deposits',period='3A; ca. 2600 BCE',basis='Excavators report context and calendar attribution; no sample identifier or lot on this page.',eligibility='potential independently contextualized early fragment; completeness must be resolved without text selection'),
rec('H-1689',[10],mound='E, western edge',deposit='deposit containing Early Harappan and Harappan pottery',period='3A or beginning 3B',basis='Mixed ceramic association; carving style helps proposed placement.',eligibility='ambiguous early boundary; exclude from strict 3A/3B versus 3C assignment pending field context'),
rec('H-1682',[10],mound='E, eastern edge',deposit='nearby trench',period='3B',basis='Explicit Period 3B context; lot and underlying association not supplied.',eligibility='candidate early seal; obtain field lot and independent phase evidence'),
rec('H-1683',[10],mound='E, northeastern slope',deposit='slope',basis='Unfinished seal compared stylistically with H-1682.',eligibility='exclude unfinished seal from completed-legend comparison; no independent period'),
rec('H-1692',[11],mound='E, northeastern edge',deposit='dustbin outside a house',period='3B',basis='Associated house dated to Period 3B; no lot or sample link supplied.',eligibility='candidate early seal; verify dustbin stratigraphic relation to dated house'),
rec('H-1537',[4,12],deposit='mixed context',period='3C; formerly 2',basis='Microscopic tool marks, carving technique and glaze; comparison with securely contextualized seals.',eligibility='exclude from independent clock; dating depends on seal traits')]
(raw/'context-records-v1.json').write_text(json.dumps({'schema_version':1,'scope':'source assertions; no corpus-text join','records':rows},indent=2),encoding='utf8')
manifest={'sources':[{'id':'KM2010','title':'Inscribed Objects from Harappa Excavations 1986–2007','authors':['J. Mark Kenoyer','Richard H. Meadow'],'year':2010,'url':'https://www.harappa.com/sites/default/files/pdf/KenoyerMeadow%202010%20Inscribed%20Objects%20from%20Harappa.pdf','logical_path':str(source).replace('\\','/'),'physical_path':str(source.resolve()),'bytes':source.stat().st_size,'sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'retrieval':'held witness, acquired 2026-10-02; inspected 2026-10-24','rights':'unverified; local-only PDF and extracted text','displayed_pdf_pages':pages,'content_exposure':'text extraction only; narrative descriptions of sign forms and counts present on pages 10–11; no images or corpus payload displayed','lineage':'excavators primary synthesis; assertions on different pages are not independent corroboration'}],'access_failures':[{'url':'https://www.harappa.com/sites/default/files/pdf/Kenoyer2009%20Indus%20Seals_0.pdf','date':'2026-10-24','ordinary_https':'HTTP 403','web_open':'content length 28208521 exceeds tool limit','search_exposure':'H99-4064 attributed late Period 3C (2000–1900 BC); unverified snippet, excluded from date record'}],'derivative':{'logical_path':'data/raw/2026-10-24-harappa-context-extension/2010-selected-text.txt','physical_path':str(raw/'2010-selected-text.txt'),'sha256':hashlib.sha256((raw/'2010-selected-text.txt').read_bytes()).hexdigest(),'rights':'local only'}}
(p/'source-manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf8')
summary={'version':1,'source_qualified_records':len(rows),'registered_key_block':3,'context_examples':6,'complete_uncontested_registration_lot_item':2,'contradictory_lot':1,'early_context_candidates':3,'mixed_context_boundary_candidate':1,'independent_calendar_sample_links':0,'manufacture_dates':0,'new_independently_dated_confirmation_seals':0,'new_physical_objects_claimed':0,'corpus_payloads_opened':0,'figures_opened':0,'scored_statistics':0,'global_coverage_gain':'not measured; source-ledger extension only'}
(p/'summary-v1.json').write_text(json.dumps(summary,indent=2))
checks={'unique_cisi':len({r['cisi'] for r in rows})==9,'no_manufacture_dates':all(r['manufacture_date'] is None for r in rows),'no_sample_links':all(r['radiocarbon_sample'] is None for r in rows),'lot_conflict_retained':rows[1]['excavation_unit'] is None and '7158' in rows[1]['conflict'] and '7458' in rows[1]['conflict'],'two_exact_keys':sum(r['registration'] is not None and r['excavation_unit'] is not None for r in rows)==2,'no_text_fields':all(not any(k in r for k in ['signs','legend','transcription']) for r in rows)}
(p/'validation-v1.json').write_text(json.dumps({'author_checks':checks,'all_pass':all(checks.values()),'verification_tier':'submitted'},indent=2))

